  }

  // Fatjar
  const f = status.fatjar || {};
  if (f.verified) {
    setCardState("status-fatjar", "verified", `${f.path}`, "ok");
  } else if (f.exists) {
    setCardState("status-fatjar", "found, verifying…", f.path, "warn");
