  if (repro.target) {
    const exp = Object.entries(repro.target.expected_scores || {}).map(([k, v]) => `${k}=${v}`).join(", ");
    setCardState(
      "status-reproduction",
      "found",
      `config=${repro.config}, condition=${repro.target.condition_name}, expected ${exp || "(none)"}`,
      "ok",
    );
