  }

  // NFCorpus
  const nfc = status.nfcorpus || {};
  const entry = nfc.registry_entry;
  if (nfc.ready) {
    setCardState(
      "status-nfcorpus",
      "ready",
      entry ? `${entry.documents} docs, ${entry.unique_terms} unique terms, ~${Math.round((entry.size || 0) / 1024 / 1024)} MB` : "",
