    setCardState("status-fatjar", "found, verifying…", f.path, "warn");
  } else {
    setCardState("status-fatjar", "missing", f.path || "ANSERINI_JAR not set", "bad");
  }

  // NFCorpus
  const nfc = status.nfcorpus || {};
  const entry = nfc.registry_entry;
  if (nfc.ready) {
